/* Real project screenshots, paired with a reading-driven checklist. */
(() => {
 const img=(name,alt)=>`<img src="assets/seo/${name}.webp" alt="${alt}" loading="lazy">`;
 const tasks=[['research','竞品调研'],['keywords','追踪高频关键词'],['writing','写作要点']];
 window.SEO_INSIGHT_HTML=`<div class="seo-insight-grid"><dl class="seo-brief">${[['项目背景','为 BC 雅思撰写 SEO 长文，回应留学人群在语言考试选择阶段产生的搜索需求。'],['目标受众','计划前往海外或港澳台留学、有语言要求的学生。'],['核心问题','如何通过竞品相关搜索内容，让 BC 雅思进入用户的考试选择范围？'],['写作目标','围绕不同语言考试及服务机构的差异布局关键词，为用户提供清晰、可信的比较信息，同时为 BC 雅思获取自然搜索流量。']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="seo-search-scene"><span class="seo-desk-note handwritten">用户搜索时，究竟在想什么</span><form class="seo-search" aria-label="体验留学考试搜索"><span class="seo-query">雅思和 XX 怎么选<i class="seo-caret" aria-hidden="true"></i></span><button type="submit" aria-label="搜索雅思和其他考试如何选择"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg></button></form><div class="seo-thoughts" aria-live="polite">${['哪项考试在留学认可度更高？','谁更容易出分？','哪家服务更好？'].map((s,i)=>`<p hidden style="--order:${i}">${s}</p>`).join('')}</div><span class="seo-search-invitation">搜寻查看问题背后的问题</span></div></div><div class="seo-core-insight"><span>THE OPPORTUNITY</span><p>用户搜索竞品，并不代表已经作出选择。</p><div>他们仍在收集信息、比较选择。认可度、出分难度和服务体验背后的多重焦虑，正是 BC 雅思通过专业比较内容进入决策过程的机会。</div></div><div class="seo-relationship"><span>客户 <b>BC 雅思</b></span><span>竞品 <b>托福 / 多邻国 / PTE / IDP 雅思</b></span></div>`;
 window.SEO_STRATEGY_HTML=`<p class="seo-strategy-lead">把搜索需求，整理成一篇有依据、有重点的比较文章。</p><div class="seo-research-desk"><aside class="seo-folder" aria-label="SEO 写作进度"><div class="seo-folder-tab">BC IELTS / SEO</div><div class="seo-folder-sheet"><div class="seo-folder-heading"><span>CHECKING LIST</span><span class="seo-progress" role="status" aria-live="polite">0 / 3</span></div><p class="handwritten">写之前，先把问题理清。</p><ol class="seo-checks">${tasks.map(([key,title],i)=>`<li data-seo-check="${key}"><span class="seo-check-box" aria-hidden="true"><svg viewBox="0 0 36 32"><path d="m4 16 9 10L32 4"/></svg></span><span>0${i+1}　${title}</span><span class="seo-check-status">待阅读</span></li>${i===2?'<li class="seo-subtask">专业人士视角</li><li class="seo-subtask">关键词布局</li><li class="seo-subtask">痛点开篇</li>':''}`).join('')}</ol><div class="seo-folder-bottom"><span>RESEARCH → KEYWORDS → COPY</span><b class="seo-done-stamp" aria-hidden="true">READY TO WRITE</b></div></div><i class="seo-folder-clip" aria-hidden="true"></i></aside><div class="seo-materials"><article class="seo-material" data-seo-task="research"><div class="seo-material-heading"><span>01 / COMPETITOR RESEARCH</span><h3>竞品调研</h3></div><div class="seo-research-board"><figure class="seo-paper">${img('research-table','原项目 BC 雅思与 IDP 雅思竞品调研表截图')}</figure><span class="seo-research-tag seo-tag-a">前期准备工作</span><span class="seo-research-tag seo-tag-b">竞品调研</span><span class="seo-research-tag seo-tag-c">寻找己方用户利益点</span><span class="seo-research-tag seo-tag-d">积累话术进入共享库</span></div><p>比较考试与服务机构的差异，从资料中寻找能回应用户疑问的利益点，再把可复用表达积累进共享话术库。</p></article><article class="seo-material" data-seo-task="keywords"><div class="seo-material-heading"><span>02 / KEYWORD TRACKING</span><h3>追踪高频关键词</h3></div><figure class="seo-paper seo-keyword-paper"><i class="seo-paper-tape" aria-hidden="true"></i><div class="seo-table-scroll" tabindex="0" role="region" aria-label="关键词工作表，可横向滚动">${img('keywords','关键词工作截图：留学相关搜索词、月均搜索指数及市场出价')}</div></figure><p>结合搜索词和搜索指数理解用户关心的问题，围绕考试及服务机构的差异组织核心词与长尾词。</p><div class="seo-keyword-note"><span class="handwritten">从搜索词，走近真实需求 ↗</span></div></article><article class="seo-material seo-sample" data-seo-task="writing"><div class="seo-material-heading"><span>03 / WRITING NOTES</span><h3>写作要点</h3></div><figure class="seo-paper seo-crop seo-full-sample"><i class="seo-pin" aria-hidden="true"></i>${img('article','真实文章样例截图：BC 与 IDP 比较文章的标题与完整开篇')}</figure></article><div class="seo-desk-finish"><span class="handwritten">从资料桌，到读者的选择里。</span><p>用专业比较承接搜索，让 BC 雅思进入尚未完成的考试决策。</p><a href="index.html#writing-seo" class="inline-link">返回 SEO 文案 ↩</a></div></div></div>`;
 document.addEventListener('DOMContentLoaded',()=>{
  if(new URLSearchParams(location.search).get('project')!=='seo')return;
  document.body.classList.add('seo-page');
  const scene=document.querySelector('.seo-search-scene');
  document.querySelector('.seo-search').addEventListener('submit',e=>{e.preventDefault();if(scene.classList.contains('is-searched'))return;scene.querySelectorAll('.seo-thoughts p').forEach(p=>p.hidden=false);requestAnimationFrame(()=>scene.classList.add('is-searched'));});
  const completed=new Set(),checks=[...document.querySelectorAll('[data-seo-check]')];
  const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;const key=e.target.closest('[data-seo-task]').dataset.seoTask;if(!completed.has(key)){completed.add(key);const check=checks.find(c=>c.dataset.seoCheck===key);check.classList.add('is-checked');check.querySelector('.seo-check-status').textContent='已阅读';document.querySelector('.seo-progress').textContent=`${completed.size} / 3`;if(completed.size===3)document.querySelector('.seo-folder').classList.add('is-complete');}observer.unobserve(e.target);}),{rootMargin:'-34% 0px -16% 0px',threshold:0});
  document.querySelectorAll('[data-seo-task] .seo-paper').forEach(el=>observer.observe(el));
  const chapter=document.querySelector('#chapter-2');let queued=false;
  const sync=()=>{document.documentElement.classList.toggle('seo-reading-strategy',chapter.getBoundingClientRect().top<innerHeight*.65);queued=false;};
  addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(sync);}},{passive:true});addEventListener('resize',sync);sync();
 });
})();
